insert into public.legal_references (id, short_name, citation, summary, url) values ('CF_1_III', 'Constituição, art. 1º, III', 'Constituição Federal de 1988, art. 1º, III (dignidade da pessoa humana) e art. 5º, III', 'A dignidade da pessoa humana é fundamento da República; ninguém será submetido a tratamento desumano ou degradante.', 'https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm');
insert into public.legal_references (id, short_name, citation, summary, url) values ('CP_149', 'Código Penal, art. 149', 'Decreto-Lei 2.848/1940, art. 149 (redação da Lei 10.803/2003)', 'Redução a condição análoga à de escravo: trabalho forçado, jornada exaustiva, condições degradantes, restrição de locomoção por dívida; retenção de documentos e cerceamento de transporte (§1º).', 'https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm');
insert into public.legal_references (id, short_name, citation, summary, url) values ('CP_149A', 'Código Penal, art. 149-A', 'Decreto-Lei 2.848/1940, art. 149-A (incluído pela Lei 13.344/2016)', 'Tráfico de pessoas: agenciar, recrutar, transportar ou alojar pessoa mediante grave ameaça, violência, coação, fraude ou abuso, para trabalho escravo, servidão, exploração sexual, entre outros.', 'https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm');
insert into public.legal_references (id, short_name, citation, summary, url) values ('CP_206', 'Código Penal, art. 206', 'Decreto-Lei 2.848/1940, art. 206', 'Recrutar trabalhadores, mediante fraude, com o fim de levá-los para território estrangeiro.', 'https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm');
insert into public.legal_references (id, short_name, citation, summary, url) values ('CP_207', 'Código Penal, art. 207', 'Decreto-Lei 2.848/1940, art. 207, §1º', 'Aliciar trabalhadores para outra localidade do país; inclui recrutar mediante fraude ou cobrança de qualquer quantia do trabalhador.', 'https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm');
insert into public.legal_references (id, short_name, citation, summary, url) values ('LEI_13344', 'Lei 13.344/2016', 'Lei 13.344, de 6 de outubro de 2016', 'Dispõe sobre prevenção e repressão ao tráfico de pessoas e medidas de atenção às vítimas.', 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2016/lei/l13344.htm');
insert into public.legal_references (id, short_name, citation, summary, url) values ('LEI_7064', 'Lei 7.064/1982', 'Lei 7.064/1982 (trabalhadores contratados no Brasil para trabalhar no exterior)', 'Exige contrato escrito com salário, condições e garantias para quem é contratado no Brasil para trabalhar no exterior.', 'https://www.planalto.gov.br/ccivil_03/leis/l7064.htm');
insert into public.legal_references (id, short_name, citation, summary, url) values ('PALERMO', 'Protocolo de Palermo', 'Protocolo Adicional à Convenção da ONU contra o Crime Organizado Transnacional (Decreto 5.017/2004), art. 3º, b', 'O consentimento da vítima é irrelevante quando obtido por engano, fraude, coação ou abuso de vulnerabilidade.', 'https://www.planalto.gov.br/ccivil_03/_ato2004-2006/2004/decreto/d5017.htm');
insert into public.legal_references (id, short_name, citation, summary, url) values ('OIT_INDICADORES', 'OIT — Indicadores de trabalho forçado', 'OIT. ILO Indicators of Forced Labour. Genebra, 2012', '11 indicadores: abuso de vulnerabilidade, engano, restrição de movimento, isolamento, violência, ameaças, retenção de documentos, retenção de salários, servidão por dívida, condições abusivas, horas extras excessivas.', 'https://www.ilo.org/publications/ilo-indicators-forced-labour');
insert into public.legal_references (id, short_name, citation, summary, url) values ('OIT_OPERACIONAIS', 'OIT/Comissão Europeia — indicadores operacionais', 'OIT; Comissão Europeia. Operational indicators of trafficking in human beings. 2009', 'Indicadores de recrutamento enganoso (natureza do trabalho, local, empregador, salário, condições, documentos) e coercitivo.', 'https://www.ilo.org/publications/operational-indicators-trafficking-human-beings');
insert into public.legal_references (id, short_name, citation, summary, url) values ('OIT_RECRUTAMENTO', 'OIT — Recrutamento equitativo', 'OIT. General principles and operational guidelines for fair recruitment and definition of recruitment fees and related costs. 2019', 'Nenhuma taxa de recrutamento ou custo relacionado deve ser cobrado do trabalhador; contrato claro e transparente antes da partida.', 'https://www.ilo.org/publications/general-principles-and-operational-guidelines-fair-recruitment-and-definition');
insert into public.legal_references (id, short_name, citation, summary, url) values ('OIT_C181', 'OIT — Convenção 181, art. 7', 'OIT. Convenção 181 sobre Agências de Emprego Privadas, 1997, art. 7', 'Agências privadas não devem cobrar, direta ou indiretamente, honorários ou custos dos trabalhadores.', 'https://normlex.ilo.org/dyn/nrmlx_en/f?p=NORMLEXPUB:12100:0::NO::P12100_ILO_CODE:C181');
insert into public.legal_references (id, short_name, citation, summary, url) values ('ONU_SEA_2023', 'ONU/ACNUDH 2023 — centros de golpes', 'ACNUDH. Online scam operations and trafficking into forced criminality in Southeast Asia: recommendations for a human rights response. Bangkok, ago. 2023', 'Recrutamento por ofertas falsas de emprego (atendimento, TI, cripto, marketing) com salário alto e viagem paga; vítimas levadas a centros de golpes em Mianmar, Camboja, Laos.', 'https://digitallibrary.un.org/record/4020504');
insert into public.legal_references (id, short_name, citation, summary, url) values ('PF_SEA_2026', 'Polícia Federal 2026 — tráfico para centros de golpes', 'Polícia Federal. PF combate tráfico internacional de brasileiros para centros de golpes no Sudeste Asiático. jul. 2026', 'Operação contra aliciamento de brasileiros por falsas vagas no Sudeste Asiático.', 'https://www.gov.br/pf/pt-br/assuntos/noticias/2026/07/pf-combate-trafico-internacional-de-brasileiros-para-centros-de-golpes-no-sudeste-asiatico');
insert into public.legal_references (id, short_name, citation, summary, url) values ('MTE_CADASTRO', 'MTE — Cadastro de Empregadores', 'Cadastro de Empregadores que tenham submetido trabalhadores a condições análogas à de escravo (Portaria Interministerial MTPS/MMIRDH 4/2016 e atualizações)', 'Lista pública de empregadores autuados, após decisão administrativa final.', 'https://www.gov.br/trabalho-e-emprego/pt-br/assuntos/inspecao-do-trabalho/areas-de-atuacao/combate-ao-trabalho-escravo-e-analogo-ao-de-escravo');
insert into public.legal_references (id, short_name, citation, summary, url) values ('LGPD', 'LGPD', 'Lei 13.709/2018', 'Proteção de dados pessoais; o ELO só envia indicadores e link, nunca o perfil de quem publicou.', 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm');
insert into public.risk_indicators (id, title, description, severity, basis, rules_version) values ('COBRANCA_TAXA', 'Cobrança para conseguir a vaga', 'O anúncio pede pagamento do candidato (taxa, curso, visto, reserva da vaga). Pelas normas da OIT, quem procura emprego não deve pagar pelo recrutamento; cobranças assim também criam dívida.', 'critico', array['OIT_RECRUTAMENTO','OIT_C181','CP_207','OIT_OPERACIONAIS']::text[], '2026.11.07-2');
insert into public.risk_indicators (id, title, description, severity, basis, rules_version) values ('RETENCAO_DOCUMENTOS', 'Retenção de passaporte ou documentos', 'O texto indica que passaporte ou documentos ficarão com a empresa. Reter documentos é indicador de trabalho forçado (OIT) e está previsto no art. 149, §1º, II do Código Penal.', 'critico', array['CP_149','OIT_INDICADORES']::text[], '2026.11.07-2');
insert into public.risk_indicators (id, title, description, severity, basis, rules_version) values ('PASSAPORTE_ANTECIPADO', 'Pedido de passaporte antes de qualquer contrato', 'Pedir cópia do passaporte por mensagem antes de entrevista e contrato expõe dados e é etapa comum de recrutamento enganoso. Sozinho não prova nada.', 'medio', array['OIT_OPERACIONAIS']::text[], '2026.11.07-2');
insert into public.risk_indicators (id, title, description, severity, basis, rules_version) values ('SERVIDAO_DIVIDA', 'Dívida com passagem, moradia ou comida', 'Custos de viagem, alojamento ou alimentação descontados do salário ou a devolver. A dívida que prende o trabalhador é indicador de trabalho forçado e de condição análoga à escravidão.', 'critico', array['CP_149','OIT_INDICADORES']::text[], '2026.11.07-2');
insert into public.risk_indicators (id, title, description, severity, basis, rules_version) values ('RESTRICAO_LIBERDADE', 'Restrição de saída ou de comunicação', 'O anúncio menciona impedir saída, recolher celular ou vigilância. Restrição de movimento e isolamento são indicadores de trabalho forçado.', 'critico', array['CP_149','OIT_INDICADORES']::text[], '2026.11.07-2');
insert into public.risk_indicators (id, title, description, severity, basis, rules_version) values ('JORNADA_EXAUSTIVA', 'Jornada exaustiva', 'Jornadas de 12h ou mais por dia ou sem folga. Jornada exaustiva caracteriza condição análoga à escravidão (CP, art. 149).', 'alto', array['CP_149','OIT_INDICADORES']::text[], '2026.11.07-2');
insert into public.risk_indicators (id, title, description, severity, basis, rules_version) values ('ALOJAMENTO_ISOLADO', 'Transporte para alojamento isolado (aliciamento)', 'Oferta de levar o trabalhador para fazenda, obra, garimpo ou outro estado com alojamento no local. É o padrão de aliciamento mais comum nos resgates no Brasil; atenção redobrada se houver dívida ou falta de contrato.', 'alto', array['CP_207','CP_149','OIT_INDICADORES']::text[], '2026.11.07-2');
insert into public.risk_indicators (id, title, description, severity, basis, rules_version) values ('PADRAO_SUDESTE_ASIATICO', 'Padrão de aliciamento para centros de golpes (Sudeste Asiático)', 'Combinação documentada pela ONU, Itamaraty e Polícia Federal: vaga de atendimento/digital/cripto no Sudeste Asiático, sem exigir experiência ou com salário alto, e contato por mensageiro; muitas vezes entrada com visto de turista e transferência por terra até a fronteira (Mae Sot/Myawaddy, Sihanoukville, Triângulo Dourado). O destino SOZINHO não gera alerta.', 'alto', array['ONU_SEA_2023','PF_SEA_2026','CP_149A','CP_206']::text[], '2026.11.07-2');
insert into public.risk_indicators (id, title, description, severity, basis, rules_version) values ('SINAIS_EXPLORACAO_SEXUAL', 'Sinais associados a aliciamento para exploração sexual', 'Pedido de fotos de corpo/biquíni, ou vagas de "modelo/dançarina/acompanhante" no exterior voltadas a mulheres jovens.', 'alto', array['CP_149A','OIT_OPERACIONAIS']::text[], '2026.11.07-2');
insert into public.risk_indicators (id, title, description, severity, basis, rules_version) values ('PRESSAO_URGENCIA', 'Pressão para aceitar sem verificar', 'Urgência, "sem entrevista", "vagas limitadas" ou pedido de sigilo à família impedem que a pessoa verifique a oferta.', 'medio', array['OIT_OPERACIONAIS','OIT_RECRUTAMENTO']::text[], '2026.11.07-2');
insert into public.risk_indicators (id, title, description, severity, basis, rules_version) values ('SEM_CONDICOES_CONTRATUAIS', 'Trabalho no exterior sem contrato ou visto de trabalho mencionado', 'Vagas legítimas no exterior mencionam contrato escrito e visto de trabalho. A ausência não prova fraude, mas exige confirmação antes de viajar.', 'medio', array['LEI_7064','OIT_RECRUTAMENTO']::text[], '2026.11.07-2');
insert into public.risk_indicators (id, title, description, severity, basis, rules_version) values ('PROMESSA_VAGA', 'Promessas vagas ou fora da realidade', 'Ganho alto e fácil sem descrição real da função. Salário alto SOZINHO não é alerta: só conta junto com falta de exigências ou promessas genéricas.', 'medio', array['OIT_OPERACIONAIS']::text[], '2026.11.07-2');
insert into public.risk_indicators (id, title, description, severity, basis, rules_version) values ('CONTATO_INFORMAL', 'Contato só por mensageiro, sem canal da empresa', 'A conversa é levada para WhatsApp/Telegram/privado e não há site ou e-mail corporativo para confirmar a empresa.', 'medio', array['OIT_OPERACIONAIS']::text[], '2026.11.07-2');
insert into public.risk_indicators (id, title, description, severity, basis, rules_version) values ('INFORMACOES_CONTRADITORIAS', 'Informações da empresa contraditórias', 'Dados do anúncio não batem entre si ou com registros públicos (país, telefone, e-mail, domínio, CNPJ).', 'alto', array['OIT_OPERACIONAIS']::text[], '2026.11.07-2');
insert into public.risk_indicators (id, title, description, severity, basis, rules_version) values ('DOMINIO_RECENTE', 'Site da empresa registrado há pouco tempo', 'O domínio do site foi registrado recentemente (consulta pública RDAP). Empresas novas existem; junto com outros sinais, pede verificação.', 'medio', array['OIT_OPERACIONAIS']::text[], '2026.11.07-2');
insert into public.risk_indicators (id, title, description, severity, basis, rules_version) values ('ANUNCIO_REPLICADO', 'Mesmo anúncio publicado por empresas diferentes', 'Um texto praticamente igual já foi visto com outro nome de empresa ou outro contato — padrão de anúncios falsos reaproveitados.', 'alto', array['OIT_OPERACIONAIS']::text[], '2026.11.07-2');
insert into public.risk_indicators (id, title, description, severity, basis, rules_version) values ('CADASTRO_EMPREGADORES', 'Nome consta no Cadastro de Empregadores (lista suja)', 'Um empregador com nome/documento correspondente foi incluído pelo MTE após autuação por trabalho análogo ao de escravo. Confira se é o mesmo empregador (homônimos existem).', 'alto', array['MTE_CADASTRO','CP_149']::text[], '2026.11.07-2');
