insert into public.analyses (job_id, level, preliminary, score, indicators, verified, insufficient, justification, rules_version, created_at) select id, 'alto_risco', false, 17, '[{"id":"PASSAPORTE_ANTECIPADO","title":"Pedido de passaporte antes de qualquer contrato","severity":"medio","description":"Pedir cópia do passaporte por mensagem antes de entrevista e contrato expõe dados e é etapa comum de recrutamento enganoso. Sozinho não prova nada.","evidence":["…contada do salário nos primeiros meses. Envie foto do passaporte pelo WhatsApp. Embarque imediato, vagas…"],"basis":["OIT_OPERACIONAIS"]},{"id":"SERVIDAO_DIVIDA","title":"Dívida com passagem, moradia ou comida","severity":"critico","description":"Custos de viagem, alojamento ou alimentação descontados do salário ou a devolver. A dívida que prende o trabalhador é indicador de trabalho forçado e de condição análoga à escravidão.","evidence":["…ecisa experiência, treinamento do zero. Passagem aérea paga pela empresa e descontada do salário nos primeiros meses. Envie f…"],"basis":["CP_149","OIT_INDICADORES"]},{"id":"PADRAO_SUDESTE_ASIATICO","title":"Padrão de aliciamento para centros de golpes (Sudeste Asiático)","severity":"alto","description":"Combinação documentada pela ONU, Itamaraty e Polícia Federal: vaga de atendimento/digital/cripto no Sudeste Asiático, sem exigir experiência ou com salário alto, e contato por mensageiro; muitas vezes entrada com visto de turista e transferência por terra até a fronteira (Mae Sot/Myawaddy, Sihanoukville, Triângulo Dourado). O destino SOZINHO não gera alerta.","evidence":["Atendente bilíngue Tailândia — salário em dólar Siam Star Recruitmen…","…dólar Siam Star Recruitment (fictícia) Bangkok, Tailândia US$ 2.300 Vaga de atendiment…","Combinação: trabalho de atendimento/digital + não exige experiência + salário muito acima do usual (us$ 2.300 ) + contato só por mensageiro + viagem/hospedagem pagas pela empresa"],"basis":["ONU_SEA_2023","PF_SEA_2026","CP_149A","CP_206"]},{"id":"PRESSAO_URGENCIA","title":"Pressão para aceitar sem verificar","severity":"medio","description":"Urgência, \"sem entrevista\", \"vagas limitadas\" ou pedido de sigilo à família impedem que a pessoa verifique a oferta.","evidence":["…porte pelo WhatsApp. Embarque imediato, vagas limitadas, responda hoje!","…pp. Embarque imediato, vagas limitadas, responda hoje!","…Envie foto do passaporte pelo WhatsApp. Embarque imediato, vagas limitadas, responda hoje!"],"basis":["OIT_OPERACIONAIS","OIT_RECRUTAMENTO"]},{"id":"SEM_CONDICOES_CONTRATUAIS","title":"Trabalho no exterior sem contrato ou visto de trabalho mencionado","severity":"medio","description":"Vagas legítimas no exterior mencionam contrato escrito e visto de trabalho. A ausência não prova fraude, mas exige confirmação antes de viajar.","evidence":["O texto fala em trabalho no exterior e não menciona contrato nem visto de trabalho."],"basis":["LEI_7064","OIT_RECRUTAMENTO"]},{"id":"PROMESSA_VAGA","title":"Promessas vagas ou fora da realidade","severity":"medio","description":"Ganho alto e fácil sem descrição real da função. Salário alto SOZINHO não é alerta: só conta junto com falta de exigências ou promessas genéricas.","evidence":["Atendente bilíngue Tailândia — salário em dólar Siam Star Recruitment (fictícia) Bangko…","Salário de us$ 2.300  (≈ R$ 12.650/mês) sem exigir experiência."],"basis":["OIT_OPERACIONAIS"]},{"id":"CONTATO_INFORMAL","title":"Contato só por mensageiro, sem canal da empresa","severity":"medio","description":"A conversa é levada para WhatsApp/Telegram/privado e não há site ou e-mail corporativo para confirmar a empresa.","evidence":["…os meses. Envie foto do passaporte pelo WhatsApp. Embarque imediato, vagas limitadas, re…"],"basis":["OIT_OPERACIONAIS"]}]'::jsonb, '[{"item":"Salário identificado","value":"us$ 2.300  (≈ R$ 12.650/mês, câmbio de referência)","source":"Texto do anúncio"}]'::jsonb, '["Não encontramos registro público que confirme a empresa \"Siam Star Recruitment (fictícia)\".","Tipo de contrato não informado.","Confirme a empresa e o visto com o consulado/embaixada do Brasil no país antes de viajar."]'::jsonb, 'Encontramos 7 sinal(is) que a OIT e a lei brasileira associam a recrutamento enganoso: pedido de passaporte antes de qualquer contrato; dívida com passagem, moradia ou comida; padrão de aliciamento para centros de golpes (sudeste asiático) e mais 4. Isso NÃO prova crime nem acusa a empresa; indica que a oferta precisa ser verificada antes de qualquer passo. Mesmo que você aceite a proposta, o consentimento obtido por engano não vale (Protocolo de Palermo): não envie documentos nem dinheiro e procure orientação.', '2026.11.07-2', '2026-10-05T12:00:00Z' from j;
